package org.pocketlab.puppy.theme

import android.content.Context
import java.io.File
import java.security.MessageDigest
import java.util.concurrent.ConcurrentHashMap
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.sync.Mutex
import kotlinx.coroutines.sync.withLock
import kotlinx.coroutines.withContext
import org.json.JSONObject

/**
 * Built-in Ghostty themes (assets/themes, generated by
 * tools/import-ghostty-themes.py) plus themes the user imported, stored as
 * their original text under `files/themes/user/`.
 *
 * Ids are stable strings: `ghostty:<upstream name>` and `user:<file stem>`.
 */
class ThemeRepository(context: Context) {
    private val appContext = context.applicationContext
    private val userDir = File(appContext.filesDir, "themes/user")
    private val cache = ConcurrentHashMap<String, TerminalTheme>()
    private val lock = Mutex()

    data class ThemeInfo(val id: String, val name: String, val kind: ThemeSource.Kind)

    data class ImportResult(
        /** The imported theme, or null when the file had errors and was not saved. */
        val theme: TerminalTheme?,
        val unsupported: List<GhosttyThemeParser.Entry>,
        val errors: List<GhosttyThemeParser.Problem>,
    )

    private class BuiltIn(val name: String, val path: String, val sha256: String)

    @Volatile private var builtIns: List<BuiltIn>? = null
    @Volatile private var snapshot: String = ""
    @Volatile private var x11: X11Colors? = null

    private fun parser(): GhosttyThemeParser {
        val colors = x11 ?: appContext.assets.open(X11_ASSET).reader().use { X11Colors.parse(it) }.also { x11 = it }
        return GhosttyThemeParser(colors)
    }

    private fun builtIns(): List<BuiltIn> {
        builtIns?.let { return it }
        val json = JSONObject(appContext.assets.open(INDEX_ASSET).bufferedReader().use { it.readText() })
        snapshot = json.getJSONObject("source").getString("snapshot")
        val arr = json.getJSONArray("themes")
        val list = (0 until arr.length()).map {
            val o = arr.getJSONObject(it)
            BuiltIn(o.getString("name"), o.getString("path"), o.getString("sha256"))
        }
        builtIns = list
        return list
    }

    /** All themes, built-in first (upstream order) then user themes by name. */
    suspend fun list(): List<ThemeInfo> = withContext(Dispatchers.IO) {
        val builtIn = builtIns().map { ThemeInfo(BUILT_IN_PREFIX + it.name, it.name, ThemeSource.Kind.BUILT_IN) }
        val user = userFiles().map { ThemeInfo(USER_PREFIX + it.nameWithoutExtension, it.nameWithoutExtension, ThemeSource.Kind.USER) }
            .sortedBy { it.name.lowercase() }
        builtIn + user
    }

    /** Number of bundled themes, from the generated index (never hard-coded). */
    suspend fun builtInCount(): Int = withContext(Dispatchers.IO) { builtIns().size }

    /** Loads and caches a theme, or returns null if it no longer exists. */
    suspend fun load(id: String): TerminalTheme? {
        cache[id]?.let { return it }
        return withContext(Dispatchers.IO) {
            val theme = when {
                id.startsWith(BUILT_IN_PREFIX) -> {
                    val name = id.removePrefix(BUILT_IN_PREFIX)
                    val entry = builtIns().firstOrNull { it.name == name } ?: return@withContext null
                    val text = appContext.assets.open(entry.path).bufferedReader().use { it.readText() }
                    parser().parse(text).toTheme(id, name, ThemeSource(ThemeSource.Kind.BUILT_IN, snapshot, entry.sha256))
                }
                id.startsWith(USER_PREFIX) -> {
                    val file = userFile(id.removePrefix(USER_PREFIX)) ?: return@withContext null
                    if (!file.isFile) return@withContext null
                    val text = file.readText()
                    parser().parse(text).toTheme(id, file.nameWithoutExtension, ThemeSource(ThemeSource.Kind.USER, "user", sha256(text)))
                }
                else -> null
            }
            theme?.also { cache[id] = it }
        }
    }

    /** [id] if it loads, otherwise the default theme. */
    suspend fun loadOrDefault(id: String?): TerminalTheme =
        id?.let { load(it) } ?: load(DEFAULT_THEME_ID) ?: error("default theme missing from assets")

    /**
     * Parses [text] as a Ghostty theme and saves it under [name]. Files with
     * invalid values are rejected; unsupported keys are kept in the stored
     * file and reported.
     */
    suspend fun import(name: String, text: String): ImportResult = withContext(Dispatchers.IO) {
        val result = parser().parse(text)
        if (!result.ok) return@withContext ImportResult(null, result.unsupported, result.errors)
        lock.withLock {
            userDir.mkdirs()
            val base = sanitize(name).ifEmpty { "Imported" }
            var stem = base
            var n = 2
            while (File(userDir, "$stem.conf").exists()) stem = "$base (${n++})"
            File(userDir, "$stem.conf").writeText(text)
            val id = USER_PREFIX + stem
            cache.remove(id)
            ImportResult(load(id), result.unsupported, result.errors)
        }
    }

    /** Deletes a user theme. Built-in themes cannot be deleted. */
    suspend fun delete(id: String): Boolean = withContext(Dispatchers.IO) {
        if (!id.startsWith(USER_PREFIX)) return@withContext false
        val file = userFile(id.removePrefix(USER_PREFIX)) ?: return@withContext false
        cache.remove(id)
        file.delete()
    }

    private fun userFiles(): List<File> =
        userDir.listFiles { f -> f.isFile && f.name.endsWith(".conf") }?.toList().orEmpty()

    /** Resolves a user theme file, refusing anything outside [userDir]. */
    private fun userFile(stem: String): File? {
        if (stem.isEmpty() || stem != sanitize(stem)) return null
        return File(userDir, "$stem.conf")
    }

    companion object {
        const val BUILT_IN_PREFIX = "ghostty:"
        const val USER_PREFIX = "user:"

        /**
         * Ghostty's own default colors ("Ghostty Default Style Dark" in the
         * snapshot), so a fresh install looks like Ghostty out of the box.
         */
        const val DEFAULT_THEME_ID = BUILT_IN_PREFIX + "Ghostty Default Style Dark"

        private const val INDEX_ASSET = "themes/index.json"
        private const val X11_ASSET = "themes/x11-rgb.txt"

        /** File-name-safe theme name: no path separators, control or reserved characters. */
        fun sanitize(name: String): String =
            name.trim().filter { it >= ' ' && it !in "/\\:*?\"<>|" }.trim('.', ' ').take(80)

        fun sha256(text: String): String =
            MessageDigest.getInstance("SHA-256").digest(text.toByteArray()).joinToString("") { "%02x".format(it) }
    }
}
